  const seen=new Set(),pool=[...shortlistCandidates(id,n.pos),...scoutPool(id,n.pos,undefined,true),...loanPool(id,n.pos)].filter(c=>c&&c.p&&!seen.has(c.p.id)&&seen.add(c.p.id));
  const room=wageCapK(id)*1.02-wageBillK(id);
